//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry after `failed_attempts` failed calls.
    pub(crate) fn delay_for_retry(&self, failed_attempts: u32) -> u64 {
        let exponent = failed_attempts.saturating_sub(1);
        let multiplier = 1u64.checked_shl(exponent).unwrap_or(u64::MAX);
        self.base_delay_ms
            .checked_mul(multiplier)
            .unwrap_or(u64::MAX)
            .min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delays_grow_and_saturate() {
        let config = RetryConfig { max_attempts: 5, base_delay_ms: 10, max_delay_ms: 25 };
        assert_eq!(config.delay_for_retry(1), 10);
        assert_eq!(config.delay_for_retry(2), 20);
        assert_eq!(config.delay_for_retry(3), 25);
        assert_eq!(config.delay_for_retry(4), 25);
    }

    #[test]
    fn huge_exponents_do_not_overflow() {
        let config = RetryConfig { max_attempts: u32::MAX, base_delay_ms: u64::MAX, max_delay_ms: 99 };
        assert_eq!(config.delay_for_retry(u32::MAX), 99);
    }
}

